import {
  Button,
  Input,
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
} from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { TriangleAlert } from "lucide-react";
import React, { useState } from "react";

const ITEM_NAMES = [
  "Associated Waveform",
  "Bravado Machine",
  "Certificate Scheme",
  "Dynamic Warp",
  "Eureka Camera",
  "Fragrance Label",
  "Gated Alchemy",
] as const;
type ItemName = (typeof ITEM_NAMES)[number];

const ITEM_NUMS = [0, 1, 2, 3, 4, 5, 6];
const COMPETITOR_BIDS: number[][] = [
  [33, 35, 58, 66, 63, 87, 31],
  [12, 11, 9, 12, 54, 8, 9],
  [9, 25, 49, 16, 1, 49, 4],
  [4, 1, 10, 2, 6, 7, 7],
];
const COMPETITOR_TOKENS: number[] = [48, 59, 49, 37];
const YOUR_TOKENS = 88;

/** Props for a single row in the auction form */
type AuctionRowProps = {
  num: number;
  itemNames: ItemName[];
  setItemNames: React.Dispatch<React.SetStateAction<ItemName[]>>;
  itemBids: string[];
  setItemBids: React.Dispatch<React.SetStateAction<string[]>>;
};

const AuctionRow: React.FC<AuctionRowProps> = ({
  num,
  itemNames,
  setItemNames,
  itemBids,
  setItemBids,
}) => {
  const handleChange = (idx: number, value: string) => {
    setItemBids((prev) => prev.map((b, i) => (i === idx ? value : b)));
  };

  const handleBlur = (idx: number) => {
    setItemBids((prev) =>
      prev.map((b, i) => {
        if (i !== idx) return b;
        const n = parseFloat(b);
        // blank or non‐numeric → default to "0"
        return isNaN(n) ? "0" : String(n);
      }),
    );
  };

  return (
    <div className="flex items-center space-x-2">
      <span>Lot {num + 1}:</span>
      <Select
        value={itemNames[num]}
        onValueChange={(newValue: ItemName) => {
          setItemNames((prev) =>
            prev.map((item, i) => (i === num ? newValue : item)),
          );
        }}
      >
        <SelectTrigger className="w-56">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {ITEM_NAMES.map((x) => (
            <SelectItem key={x} value={x}>
              {x}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      <span>Your bid:</span>
      <Input
        type="number"
        min={0}
        // value must be a string ("" or "7" or "42")
        value={itemBids[num]}
        onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
          handleChange(num, e.target.value);
        }}
        onBlur={() => {
          handleBlur(num);
        }}
        className="w-20"
      />
    </div>
  );
};

type AuctionResponseItem = {
  won: boolean;
  message: string;
};

/** Shape of the JSON response from the auction API */
type AuctionResponse = {
  inputError: string;
  summary: AuctionResponseItem;
  output: AuctionResponseItem[];
};

const computeAuctionResult = (names: ItemName[], bids: number[]) => {
  let competitorTokens = [...COMPETITOR_TOKENS];
  let yourTokens = YOUR_TOKENS;
  const whichItemsWon: boolean[] = [];
  const yourRealBids: number[] = [];
  for (let ind = 0; ind < 7; ind++) {
    const yourBid = Math.min(bids[ind], yourTokens);
    const itemNumber = names[ind].charCodeAt(0) - 65;
    const competitorBidsOnItem = COMPETITOR_BIDS.map((i, ind2) =>
      Math.min(i[itemNumber], competitorTokens[ind2]),
    );
    whichItemsWon.push(yourBid >= Math.max(...competitorBidsOnItem));
    yourRealBids.push(yourBid);
    yourTokens -= yourBid;
    competitorTokens = competitorTokens.map(
      (i, ind2) => i - competitorBidsOnItem[ind2],
    );
  }
  const summary = whichItemsWon.every((i) => i)
    ? { won: true, message: "Congratulations! You won all seven lots!" }
    : {
        won: false,
        message: `You won ${whichItemsWon.filter((i) => i).length}/7 lots.`,
      };
  const output = whichItemsWon.map((i, ind) => ({
    won: i,
    message: `Lot ${ind + 1} (${names[ind]}): Your bid of ${yourRealBids[ind]} token${yourRealBids[ind] !== 1 ? "s" : ""} ${i ? "won" : "did not win"}.`,
  }));
  return [summary, output] as const;
};

/** Run the auction: POST names & bids, then set error/output */
const runAuction = (
  itemNames: ItemName[],
  itemBids: string[],
  lastCheckTime: number,
  setLastCheckTime: React.Dispatch<React.SetStateAction<number>>,
  setError: React.Dispatch<React.SetStateAction<string>>,
  setSummary: React.Dispatch<React.SetStateAction<AuctionResponseItem>>,
  setOutput: React.Dispatch<React.SetStateAction<AuctionResponseItem[]>>,
): void => {
  if (Date.now() < lastCheckTime + 1000) {
    setError("Please wait at least one second between attempts.");
    setSummary({ won: false, message: "" });
    setOutput([]);
    return;
  }

  if (itemBids.some((b) => isNaN(parseFloat(b)))) {
    setError("Some bid is not a number!");
    setSummary({ won: false, message: "" });
    setOutput([]);
    return;
  }

  setLastCheckTime(Date.now());

  const bids = itemBids.map((i) => parseFloat(i));
  let response: AuctionResponse;
  if (new Set(itemNames).size !== 7) {
    response = {
      inputError: "Invalid permutation! (Some lot is missing/repeated)",
      summary: { won: false, message: "" },
      output: [],
    };
  } else if (bids.some((x) => x < 0 || x !== Math.floor(x))) {
    response = {
      inputError: "Bids must be non-negative integers!",
      summary: { won: false, message: "" },
      output: [],
    };
  } else {
    const [summary, output] = computeAuctionResult(itemNames, bids);
    response = { inputError: "", summary, output };
  }
  setError(response.inputError);
  setSummary(response.summary);
  setOutput(response.output);
};

export const AuctionComponent: React.FC = () => {
  const [itemNames, setItemNames] = useState<ItemName[]>([...ITEM_NAMES]);
  const [itemBids, setItemBids] = useState<string[]>(
    Array(ITEM_NAMES.length).fill("0"),
  );
  const [error, setError] = useState<string>("");
  const [summary, setSummary] = useState<AuctionResponseItem>({
    won: false,
    message: "",
  });
  const [output, setOutput] = useState<AuctionResponseItem[]>([]);

  const [lastCheckTime, setLastCheckTime] = useState<number>(0);

  return (
    <>
      <div className="flex flex-col gap-2 mt-2">
        {ITEM_NUMS.map((idx) => (
          <AuctionRow
            key={idx}
            num={idx}
            itemNames={itemNames}
            setItemNames={setItemNames}
            itemBids={itemBids}
            setItemBids={setItemBids}
          />
        ))}
      </div>
      <Button
        variant="primary"
        onClick={() => {
          runAuction(
            itemNames,
            itemBids,
            lastCheckTime,
            setLastCheckTime,
            setError,
            setSummary,
            setOutput,
          );
        }}
        className="mt-4"
      >
        See auction results
      </Button>

      {error && (
        <div className="mt-2 flex gap-1">
          <TriangleAlert className="w-6 h-6 text-red-500" />
          <p className="text-red-500">{error}</p>
        </div>
      )}
      <p
        className={cn(
          "text-lg mt-2",
          summary.won ? "text-green-500" : "text-red-500",
        )}
      >
        {summary.message}
      </p>
      <ul>
        {output.map((x, idx) => (
          <li key={idx} className={x.won ? "text-green-500" : "text-red-500"}>
            {x.message}
          </li>
        ))}
      </ul>
    </>
  );
};
