import React from "react";
import { createRoot } from "react-dom/client";
import { AuctionComponent } from "./AuctionComponent";

const elem1 = document.getElementById("auction-root");
if (elem1) {
  const root = createRoot(elem1);
  root.render(<AuctionComponent />);
} else {
  console.error(
    "Could not mount App because #auction-root was nowhere to be found",
  );
}
